class TestURLNormalization:
    """Verify scheme injection logic."""

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_prepends_http_when_no_scheme(self, mock_session_class, plugin, mock_response):
        """Target without scheme should get 'http://' prefix."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {"Content-Security-Policy": "default-src 'self'"}

        await plugin.run("example.com")

        # Extract the URL passed to session.get
        call_args = mock_session_class.return_value.get.call_args
        assert call_args is not None
        url_arg = call_args[0][0]
        assert url_arg == "http://example.com"

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_preserves_https_scheme(self, mock_session_class, plugin, mock_response):
        """Target with https:// should not be modified."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {"Content-Security-Policy": "default-src 'self'"}

        await plugin.run("https://secure.example.com")

        call_args = mock_session_class.return_value.get.call_args
        url_arg = call_args[0][0]
        assert url_arg == "https://secure.example.com"

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_preserves_http_scheme(self, mock_session_class, plugin, mock_response):
        """Target with http:// should not be modified."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {"Content-Security-Policy": "default-src 'self'"}

        await plugin.run("http://already.example.com")

        call_args = mock_session_class.return_value.get.call_args
        url_arg = call_args[0][0]
        assert url_arg == "http://already.example.com"


