class TestHeaderDetection:
    """Core detection logic for missing/present headers."""

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_all_headers_present_no_findings(self, mock_session_class, plugin, mock_response):
        """When all required headers exist, no findings should be returned."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {
            "Content-Security-Policy": "default-src 'self'",
            "X-Frame-Options": "DENY",
            "Strict-Transport-Security": "max-age=31536000",
            "X-Content-Type-Options": "nosniff",
        }

        findings = await plugin.run("https://example.com")
        assert findings == []

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_single_missing_header(self, mock_session_class, plugin, mock_response):
        """One missing header should produce exactly one LOW finding."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {
            "Content-Security-Policy": "default-src 'self'",
            "X-Frame-Options": "DENY",
            "Strict-Transport-Security": "max-age=31536000",
            # X-Content-Type-Options missing
        }

        findings = await plugin.run("https://example.com")

        assert len(findings) == 1
        finding = findings[0]
        assert finding.plugin_id == "HTTP_AUDIT_01"
        assert finding.severity == Severity.LOW
        assert finding.title == "Missing Security Header: X-Content-Type-Options"
        assert "X-Content-Type-Options" in finding.evidence

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_multiple_missing_headers(self, mock_session_class, plugin, mock_response):
        """Multiple missing headers should produce one finding per header."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {}  # All missing

        findings = await plugin.run("https://example.com")

        assert len(findings) == len(plugin.REQUIRED_HEADERS)
        missing_titles = {f.title for f in findings}
        for header in plugin.REQUIRED_HEADERS:
            assert f"Missing Security Header: {header}" in missing_titles

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_finding_evidence_contains_url(self, mock_session_class, plugin, mock_response):
        """Evidence should reference the target URL."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {}

        findings = await plugin.run("https://example.com")

        assert all("https://example.com" in f.evidence for f in findings)

    @pytest.mark.asyncio
    @patch("aiohttp.ClientSession")
    async def test_case_sensitive_header_matching(self, mock_session_class, plugin, mock_response):
        """HTTP headers are case-insensitive per RFC 7230, but the plugin uses exact match.
        This test documents current behavior: lowercase headers are treated as missing."""
        mock_session_class.return_value.__aenter__.return_value = mock_session
        mock_response.headers = {
            "content-security-policy": "default-src 'self'",  # lowercase
            "X-Frame-Options": "DENY",
            "Strict-Transport-Security": "max-age=31536000",
            "X-Content-Type-Options": "nosniff",
        }

        findings = await plugin.run("https://example.com")

        # Current implementation does exact dict lookup, so lowercase is missed.
        assert len(findings) == 1
        assert findings[0].title == "Missing Security Header: Content-Security-Policy"


